      <div class="aods-field"><label class="aods-label">Group</label><div class="aods-select"><button class="aods-select__trigger" type="button" id="sel-a" aria-haspopup="listbox" aria-expanded="false" aria-controls="sel-a-list" data-placeholder>Select a group</button><ul class="aods-menu aods-select__list" id="sel-a-list" role="listbox" hidden><li class="aods-menu__item aods-select__option" role="option" data-value="programs">Group one</li><li class="aods-menu__item aods-select__option" role="option" data-value="operations">Group two</li><li class="aods-menu__item aods-select__option" role="option" data-value="planning">Group three</li><li class="aods-menu__item aods-select__option" role="option" data-value="grants">Group four</li><li class="aods-menu__item aods-select__option" role="option" data-value="safety">Group five</li><li class="aods-menu__item aods-select__option" role="option" data-value="research">Group six</li><li class="aods-menu__item aods-select__option" role="option" data-value="data">Group seven</li><li class="aods-menu__item aods-select__option" role="option" data-value="field-services">Group eight</li></ul><select class="aods-select__native" tabindex="-1" aria-hidden="true"><option value="programs">Group one</option><option value="operations">Group two</option><option value="planning">Group three</option><option value="grants">Group four</option><option value="safety">Group five</option><option value="research">Group six</option><option value="data">Group seven</option><option value="field-services">Group eight</option></select></div></div>
